xml.Script:
        R := 0.4;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';
        include 'Figures\Scripts\Dodecahedron_Standard_Colors.inc';
        D := (Rsin + R2sin) / 2;

        // half centers of cores
        Tx[0] := Cx[2] / RSin * D;
        Ty[0] := Cy[2] / RSin * D;
        Tz[0] := Cz[2] / RSin * D;
        Tx[1] := Cx[4] / RSin * D;
        Ty[1] := Cy[4] / RSin * D;
        Tz[1] := Cz[4] / RSin * D;

        procedure Exchange2Colors(c1, c2);
        begin
            C := Colors[c1];
            Colors[c1] := Colors[c2];
            Colors[c2] := C;
        end;

        procedure ReflectColors();
        begin
            Exchange2Colors( 0, 3);
            Exchange2Colors( 5, 6);
            Exchange2Colors( 8,11);
            Exchange2Colors( 1,10);
        end;

xml.Figure:
        
              
        

        
             // V[v] - C[c] = vector of turning symmetry
        

        
            
            
            
            
            
        

        // central core
        
        
        
        

         ReflectColors;
